                        .HasColumnName("state_code")
                        .IsFixedLength();

                    b.Property<string>("TradeName")
                        .HasMaxLength(250)
                        .HasColumnType("character varying(250)")
                        .HasColumnName("trade_name");

                    b.Property<DateTimeOffset>("UpdatedAtUtc")
                        .HasColumnType("timestamp with time zone")
                        .HasColumnName("updated_at_utc");

                    b.HasKey("Id")
                        .HasName("pk_gst_registrations");

                    b.HasAlternateKey("Id", "ClientId")
                        .HasName("ak_gst_registrations_id_client");

                    b.HasIndex("ClientId")
                        .IsUnique()
                        .HasDatabaseName("ux_gst_registrations_primary")
                        .HasFilter("is_primary AND is_active");

                    b.HasIndex("Gstin")
                        .IsUnique()
                        .HasDatabaseName("ux_gst_registrations_gstin");

                    b.HasIndex("ClientId", "IsActive")
                        .HasDatabaseName("ix_gst_registrations_client_active");

                    b.HasIndex("StateCode", "IsActive")
                        .HasDatabaseName("ix_gst_registrations_state_active");

                    b.ToTable("gst_registrations", "clients", t =>
                        {
                            t.HasCheckConstraint("ck_gst_registrations_dates", "effective_to IS NULL OR effective_from IS NULL OR effective_to >= effective_from");

                            t.HasCheckConstraint("ck_gst_registrations_shape", "gstin ~ '^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z][0-9A-Z]Z[0-9A-Z]$'");

                            t.HasCheckConstraint("ck_gst_registrations_state", "substring(gstin from 1 for 2) = state_code");

                            t.HasCheckConstraint("ck_gst_registrations_status", "registration_status IN ('ACTIVE', 'INACTIVE', 'CANCELLED', 'SUSPENDED')");
                        });
                });

